func (m InventoryScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m InventoryScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

// D10: rescanCmd had no starting message at all — only a finished one — so its
// items would have jumped straight from queued to done and the distinction
//
// cloneFound and cloneWalkFailed both set Discover, because both name a target
// the run has never heard of — the walk is what finds them (D3). The others
// address a row that exists.

func (m CloneEventMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindClone, Target: m.event.path}
	switch m.event.kind {
	case cloneFound:
		t.State, t.Discover = jobs.ItemQueued, true
	case cloneBegan:
		t.State = jobs.ItemRunning
	case cloneEnded:
		switch {
		case m.event.err != nil:
			t.State, t.Detail = jobs.ItemFailed, m.event.err.Error()
		case m.event.skipped:
			// Not a failure and not work: the directory was already there, and
			// decision 2 says the explorer leaves what exists alone.
			t.State = jobs.ItemSkipped
		default:
			t.State = jobs.ItemDone
		}
	case cloneWalkFailed:
		// A group that could not be listed gets a row of its own rather than
		// being folded into a repository's error: the repositories under it
		// were never discovered, so no other row can stand for them. It is
		// discovered *as* a failure — there was never a queued state for it.
		t.State, t.Detail, t.Discover = jobs.ItemFailed, "discovery: "+m.event.err.Error(), true
	}
	return t
//
// The mapping lives here rather than in the router for the reason Reporter
// exists: "a project whose template failed still exists" is this package's
// vocabulary, and a router that knew it would grow a branch per view.

func (m GroupCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	}
	return t
}

func (m ProjectCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	switch {
	case m.Error != nil && m.TemplateUnavailable:
		// Nothing was created: the template was fetched first, and could not be.
		t.State = jobs.ItemFailed
		t.Detail = "template unavailable — nothing was created"
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	case m.TemplateError != nil:
		// The project exists, empty, but what was asked for was a repository
		// with a template in it: the run says it did not get there rather than
		// reading as a success. The row still settles (handleProjectCreated).
		t.State = jobs.ItemFailed
		t.Detail = "created empty — the template's commit failed"
	}
	return t
}

func (m DeleteCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every message reporting on registered work can be
// applied to the registry. One added without it would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
	}

	job := scanJob{
		entry: entry,
		creds: template.CredentialsFor(m.config, m.secrets, entry.Source),
		cache: m.cache,
		opts:  m.scanOptions(),
		run:   m.scanner,
	}
	run := jobs.NewRun(jobs.KindScan, command.ViewTemplates, "", entry.Name, dir)
	return m, jobs.StartInContext(run, func(contextName string) tea.Cmd {
		return scanTemplateCmd(job, contextName)
	})
}

